<script setup lang="ts">
import AppIcon from "./AppIcon.vue";
import { analysisFields, analysisOperators, isConditionGroup, type AnalysisCondition, type AnalysisConditionGroup } from "../analysisRules";
const props = withDefaults(defineProps<{ group: AnalysisConditionGroup; label: string; remaining: number; depth?: number }>(), { depth: 0 });
const emit = defineEmits<{ change: [group: AnalysisConditionGroup]; remove: [] }>();
function replace(index: number, node: AnalysisCondition | AnalysisConditionGroup) { emit("change", { ...props.group, conditions: props.group.conditions.map((item, i) => i === index ? node : item) }); }
function update(index: number, condition: AnalysisCondition, changes: Partial<AnalysisCondition>) { replace(index, { ...condition, ...changes }); }
function changeField(index: number, condition: AnalysisCondition, field: string) { update(index, condition, { field, operator: analysisOperators(field)[0]!.value, value: "", value2: "" }); }
function remove(index: number) { emit("change", { ...props.group, conditions: props.group.conditions.filter((_, i) => i !== index) }); }
</script>
<template>
  <div class="analysis-condition-group" :class="{ nested: depth > 0 }" role="group" :aria-label="`${label} conditions`">
    <div class="condition-group-heading"><select :value="group.mode" :aria-label="`${label} condition mode`" @change="emit('change', { ...group, mode: ($event.target as HTMLSelectElement).value })"><option value="all">Match all (AND)</option><option value="any">Match any (OR)</option></select><button v-if="depth" class="icon-button danger" :aria-label="`Remove ${label.toLowerCase()}`" title="Remove this group and its conditions." @click="emit('remove')"><AppIcon name="trash" /></button></div>
    <p v-if="!group.conditions.length" class="field-hint">No conditions: matches every row of the chosen type.</p>
    <template v-for="(condition, c) in group.conditions" :key="c">
      <AnalysisConditionGroup v-if="isConditionGroup(condition)" :group="condition" :label="`${label} group ${c + 1}`" :remaining="remaining" :depth="depth + 1" @change="replace(c, $event)" @remove="remove(c)" />
      <div v-else class="rule-condition"><select :value="condition.field" :aria-label="`${label} condition ${c + 1} field`" @change="changeField(c, condition, ($event.target as HTMLSelectElement).value)"><option v-for="field in analysisFields" :key="field.value" :value="field.value">{{ field.label }}</option></select><select :value="condition.operator" :aria-label="`${label} condition ${c + 1} operator`" @change="update(c, condition, { operator: ($event.target as HTMLSelectElement).value, value: '', value2: '' })"><option v-for="operator in analysisOperators(condition.field)" :key="operator.value" :value="operator.value">{{ operator.label }}</option></select><div class="condition-values"><input v-if="!['is_empty', 'not_empty'].includes(condition.operator)" :value="condition.value" :aria-label="`${label} condition ${c + 1} value`" :placeholder="condition.operator === 'contains' ? 'Text (blank matches all)' : condition.field === 'value' ? 'Number or expression' : 'Text'" @input="update(c, condition, { value: ($event.target as HTMLInputElement).value })" /><template v-if="condition.operator === 'between'"><span>and</span><input :value="condition.value2" :aria-label="`${label} condition ${c + 1} upper value`" placeholder="Upper bound" @input="update(c, condition, { value2: ($event.target as HTMLInputElement).value })" /></template></div><button class="icon-button danger" :aria-label="`Remove ${label.toLowerCase()} condition ${c + 1}`" title="Remove this condition." @click="remove(c)"><AppIcon name="trash" /></button></div>
    </template>
    <div class="project-tools"><button class="text-button" :disabled="group.conditions.length >= 8 || remaining <= 0" :aria-label="`Add ${label.toLowerCase()} condition`" @click="emit('change', { ...group, conditions: [...group.conditions, { field: 'description', operator: 'contains', value: '' }] })">Add condition</button><button v-if="depth < 2" class="text-button" :disabled="group.conditions.length >= 8 || remaining <= 0" :aria-label="`Add ${label.toLowerCase()} group`" title="Combine another set of AND/OR conditions within this group." @click="emit('change', { ...group, conditions: [...group.conditions, { mode: 'any', conditions: [] }] })">Add group</button></div>
  </div>
</template>
